    /// <summary>
    /// PaffH 01.02.21
    /// check if all UserId's from table UserInfo are present in NDXUserInfo
    /// </summary>
    public static void checkFromUserInfo()
    {
        UserInfo userInfo;
        NDXUserInfo nDXUserInfo, nDXUserInfoGrp;
        SysUserLicenseCount sysUserLicenseCount;
        SysUserLicenseList sysUserLicenseList;

        RecordInsertList recordInsertList = new RecordInsertList(tableNum(NDXUserInfo));
        while select crosscompany id from userInfo
//            group by userInfo.id, nDXUserInfoGrp.UserId
            group by userInfo.id
            notexists join nDXUserInfoGrp
                where userInfo.id == nDXUserInfoGrp.UserId
                    //&& userInfo.TableRefId == tableNum(UserInfo)
        {
            nDXUserInfo.clear();
            nDXUserInfo.UserId = userInfo.id;
            nDXUserInfo.TableRefId = tableNum(UserInfo);
            recordInsertList.add(nDXUserInfo);
        }
        recordInsertList.insertDatabase();

        while select UserName from sysUserLicenseList
            join sysUserLicenseCount
                where sysUserLicenseList.SysUserLicenseCount == sysUserLicenseCount.RecId
            notexists join nDXUserInfo
                where nDXUserInfo.UserId == sysUserLicenseList.UserName
                    //&& nDXUserInfo.TableRefId == tableNum(SysUserLicenseList)
        {
            nDXUserInfo.clear();
            nDXUserInfo.UserId = sysUserLicenseList.UserName;
            nDXUserInfo.TableRefId = tableNum(SysUserLicenseList);
            recordInsertList.add(nDXUserInfo);
        }
        recordInsertList.insertDatabase();

        while select forupdate UserId from nDXUserInfo
            where nDXUserInfo.TableRefId == tableNum(UserInfo)
            notexists join userInfo
                where userInfo.id == nDXUserInfo.UserId
                    && nDXUserInfo.TableRefId == tableNum(UserInfo)
        {
            if (nDXUserInfo.validateDelete())
            {
                ttsbegin;
                nDXUserInfo.delete();
                ttscommit;
            }
        }
        while select forupdate UserId from nDXUserInfo
            where nDXUserInfo.TableRefId == tableNum(SysUserLicenseList)
            notexists join sysUserLicenseList
                where sysUserLicenseList.UserName == nDXUserInfo.UserId
                    && nDXUserInfo.TableRefId == tableNum(SysUserLicenseList)
            join sysUserLicenseCount
                where sysUserLicenseCount.recid == sysUserLicenseList.SysUserLicenseCount
        {
            if (nDXUserInfo.validateDelete())
            {
                ttsbegin;
                nDXUserInfo.delete();
                ttscommit;
            }
        }

    }

/// <summary>
/// PaffH 01.02.21
/// check the number of license relevant elements for all users
/// </summary>
public static void checkUserLicenseTypeAll()
{
    NDXUserInfo nDXUserInfo;

    NDXUserInfo::checkFromUserInfo();

    while select nDXUserInfo
    {
        nDXUserInfo.checkUserLicenseType();
    }
}

/// <summary>
/// PaffH 01.02.21
/// check the number of license relevant elements for a user
/// </summary>
public void checkUserLicenseType()
{
    NDXSecurityFilterTable nDXSecurityFilterTable;
    Query q = new Query();
    QueryRun qr;
    QueryBuildDataSource qbds1, qbds2, qbds3, qbds4;

    qbds1 = q.addDataSource(tableNum(SecurityUserRole));
    qbds1.addRange(fieldNum(SecurityUserRole, User)).value(queryValue(this.UserId));
    qbds1.orderMode(OrderMode::GroupBy);
    qbds1.relations(true);
    qbds2 = qbds1.addDataSource(tableNum(SecurityRole));
    qbds2.relations(true);
    qbds3 = qbds2.addDataSource(tableNum(NDXRoleTable));
    qbds3.relations(true);
    qbds4 = qbds3.addDataSource(tableNum(NDXSecurityFilterTable));
    qbds4.addSelectionField(fieldNum(NDXSecurityFilterTable, CountLicenseActivity), SelectionField::Sum);
    qbds4.addSelectionField(fieldNum(NDXSecurityFilterTable, CountLicenseEnterprise), SelectionField::Sum);
    qbds4.addSelectionField(fieldNum(NDXSecurityFilterTable, CountLicenseUniversal), SelectionField::Sum);
    qbds4.relations(true);

    qr=new QueryRun(q);
    qr.next();
    nDXSecurityFilterTable = qr.get(tableNum(NDXSecurityFilterTable));
    if (this.CountLicenseActivity != nDXSecurityFilterTable.CountLicenseActivity ||
        this.CountLicenseEnterprise != nDXSecurityFilterTable.CountLicenseEnterprise ||
        this.CountLicenseUniversal != nDXSecurityFilterTable.CountLicenseUniversal)
    {
        ttsbegin;
        this.selectForUpdate(true);
        this.CountLicenseActivity = nDXSecurityFilterTable.CountLicenseActivity;
        this.CountLicenseEnterprise = nDXSecurityFilterTable.CountLicenseEnterprise;
        this.CountLicenseUniversal = nDXSecurityFilterTable.CountLicenseUniversal;
        this.update();
        ttscommit;
    }
}
